rm -f $R/files/rpi4-noid-*; mdir -b -i "$S/cards/noid.img@@32256" ::/USB > $R/serial/rpi4-noid.log-usbdir.txt 2>&1
for f in $(sed -n 's#^::/USB/##p' $R/serial/rpi4-noid.log-usbdir.txt); do mcopy -n -i "$S/cards/noid.img@@32256" "::/USB/$f" "$R/files/rpi4-noid-$f"; done
rm -f $S/cards/noid.img
cp -c $S/cards/full-base.img $S/cards/full.img
$M/run-rpi.sh $K $S/cards/full.img $R/serial/rpi4-full.log "Press any key to exit" 150
mdir -i "$S/cards/full.img@@32256" ::/USB > $R/serial/rpi4-full.log-usbdir.txt 2>&1
rm -rf $S/fullout; mkdir -p $S/fullout; mcopy -n -s -i "$S/cards/full.img@@32256" ::/USB/* $S/fullout/ 2>&1 | tail -2
rm -f $S/cards/full.img $S/cards/*-base.img
